#include "Monstey_FearDbPrimitives.hpp"
#include "Monstey_Json.hpp"
#include <algorithm>
#include <array>
#include <bit>
#include <fstream>
#include <iostream>
#include <random>
#include <vector>
using namespace Monstey;
namespace {
using Monstey_U32=std::uint32_t;std::uint64_t Monstey_Cases=0,Monstey_Checks=0,Monstey_Groups=0;
void Monstey_Check(bool v,const char*text){++Monstey_Checks;if(!v)throw std::runtime_error(text);}
struct Monstey_Arena{
 Monstey_U32 base=0x10200000;std::vector<std::uint8_t>bytes=std::vector<std::uint8_t>(0x2000);
 Monstey_FearDbMemory Read()const{return{base,bytes};}Monstey_FearDbMutableMemory Write(){return{base,bytes};}
 Monstey_U32 At(Monstey_U32 off)const{return base+off;}
 void Put(Monstey_U32 off,Monstey_U32 word,unsigned width=4){if(off>bytes.size()||width>bytes.size()-off)throw std::runtime_error("Fixture store range");for(unsigned i=0;i<width;++i)bytes[off+i]=static_cast<std::uint8_t>(word>>(i*8));}
 Monstey_U32 Get(Monstey_U32 off,unsigned width=4)const{Monstey_U32 v=0;for(unsigned i=0;i<width;++i)v|=Monstey_U32(bytes.at(off+i))<<(i*8);return v;}
 void Attribute(unsigned type,Monstey_U32 count=1){Put(0x10a,type,1);Put(0x108,count,2);Put(0x10c,At(0x400));}
};
using Monstey_Scalar=Monstey_U32(*)(Monstey_FearDbMemory,Monstey_U32,Monstey_U32,Monstey_U32);
constexpr std::array<Monstey_Scalar,5>Monstey_Scalars{Monstey_FearDbInt32Bits,Monstey_FearDbFloat32Bits,Monstey_FearDbStringIdentity,Monstey_FearDbWStringIdentity,Monstey_FearDbRecordIdentity};
constexpr std::array<unsigned,5>Monstey_Types{3,2,4,5,9};
using Monstey_Vector=Monstey_U32(*)(Monstey_FearDbMutableMemory,Monstey_U32,Monstey_U32,Monstey_U32,Monstey_U32);
constexpr std::array<Monstey_Vector,3>Monstey_Vectors{Monstey_FearDbVector2,Monstey_FearDbVector3,Monstey_FearDbVector4};
void Monstey_Null(){Monstey_Arena a;const auto m=a.Read();for(auto fn:std::array{Monstey_FearDbNodeName,Monstey_FearDbNodeParentOrDatabaseName,Monstey_FearDbChildCount,Monstey_FearDbValueCount,Monstey_FearDbAttributeType,Monstey_FearDbAttributeUsage}){Monstey_Check(fn(m,0)==0,"null node metadata");++Monstey_Cases;}Monstey_Check(Monstey_FearDbHandleIndex(m,0)==UINT32_MAX,"null index sentinel");++Monstey_Cases;for(auto fn:Monstey_Scalars){Monstey_Check(fn(m,0,UINT32_MAX,0xfedcba98)==0xfedcba98,"null scalar fallback");++Monstey_Cases;}Monstey_Check(Monstey_FearDbBoolByte(m,0,UINT32_MAX,0xab)==0xab,"null bool byte");++Monstey_Cases;++Monstey_Groups;}
void Monstey_Metadata(){Monstey_Arena a;for(Monstey_U32 n=0;n<256;++n){a.Put(0x100,0x89abcdef);a.Put(0x104,0xfedcba98);a.Put(0x108,0x87650000|n*257);a.Put(0x10a,n,1);a.Put(0x10b,255-n,1);Monstey_Check(Monstey_FearDbNodeName(a.Read(),a.At(0x100))==0x89abcdef,"name field0");Monstey_Check(Monstey_FearDbNodeParentOrDatabaseName(a.Read(),a.At(0x100))==0xfedcba98,"parent field4");Monstey_Check(Monstey_FearDbValueCount(a.Read(),a.At(0x100))==n*257,"value count16");Monstey_Check(Monstey_FearDbAttributeType(a.Read(),a.At(0x100))==n,"raw type8");Monstey_Check(Monstey_FearDbAttributeUsage(a.Read(),a.At(0x100))==255-n,"raw usage8");Monstey_Check(Monstey_FearDbChildCount(a.Read(),a.At(0x100))==a.Get(0x108),"child count32");++Monstey_Cases;}++Monstey_Groups;}
void Monstey_Indices(){Monstey_Arena a;for(auto count:std::array<Monstey_U32,5>{0,1,17,0x80000000,UINT32_MAX})for(auto i:std::array<Monstey_U32,8>{0,1,16,17,65535,0x10000000,0x80000000,UINT32_MAX}){a.Put(0x108,count);a.Put(0x10c,0xfffffff0);Monstey_Check(Monstey_FearDbChildByIndex(a.Read(),a.At(0x100),i)==(i<count?Monstey_U32(0xfffffff0+i*16):0),"bounded child index");Monstey_Check(Monstey_FearDbAttributeByIndex(a.Read(),a.At(0x100),i)==Monstey_U32(0xfffffff0+i*16),"attribute must not add count guard");++Monstey_Cases;}
 std::mt19937 rng(0x73626431);for(unsigned n=0;n<10000;++n){const Monstey_U32 first=rng();a.Put(0x104,a.At(0x200));a.Put(0x20c,first);const auto h=a.At(0x100);const auto raw=Monstey_U32(h-first);const std::int64_t signedDiff=raw<0x80000000u?static_cast<std::int64_t>(raw):static_cast<std::int64_t>(raw)-0x100000000ll;const auto floor=signedDiff>=0?signedDiff/16:-((-signedDiff+15)/16);Monstey_Check(Monstey_FearDbHandleIndex(a.Read(),h)==static_cast<Monstey_U32>(floor),"signed floor index");++Monstey_Cases;}++Monstey_Groups;}
void Monstey_ScalarMatrix(){Monstey_Arena a;std::mt19937 rng(0xdead516);for(unsigned fn=0;fn<Monstey_Scalars.size();++fn)for(unsigned type=0;type<256;++type)for(auto count:std::array<Monstey_U32,4>{0,1,2,65535})for(auto index:std::array<Monstey_U32,5>{0,1,2,65535,UINT32_MAX}){a.Attribute(type,count);for(unsigned k=0;k<3;++k)a.Put(0x400+k*4,k?0xffffffffu:rng());const Monstey_U32 fallback=rng();const auto expected=type==Monstey_Types[fn]&&index<count?a.Get(0x400+index*4):fallback;const auto before=a.bytes;Monstey_Check(Monstey_Scalars[fn](a.Read(),a.At(0x100),index,fallback)==expected,"typed scalar/type/bounds/fallback");Monstey_Check(a.bytes==before,"scalar modified memory");++Monstey_Cases;}
 for(auto fn:Monstey_Scalars){a.Attribute(0);(void)fn;a.Put(0x400,0);}++Monstey_Groups;}
void Monstey_StoredZero(){Monstey_Arena a;for(unsigned n=0;n<Monstey_Scalars.size();++n){a.Attribute(Monstey_Types[n]);a.Put(0x400,0);Monstey_Check(Monstey_Scalars[n](a.Read(),a.At(0x100),0,0x12345678)==0,"stored zero replaced with default");++Monstey_Cases;}++Monstey_Groups;}
void Monstey_Bools(){Monstey_Arena a;for(unsigned b=0;b<256;++b)for(unsigned upper:std::array<unsigned,3>{0,0x12345600,0xffffff00}){a.Attribute(1);a.Put(0x400,upper|b);Monstey_Check(Monstey_FearDbBoolByte(a.Read(),a.At(0x100),0,0x99)==b,"bool must read AL byte only");Monstey_Check(Monstey_FearDbBoolByte(a.Read(),a.At(0x100),1,0xaa)==0xaa,"bool index fallback");++Monstey_Cases;}for(unsigned b=0;b<256;++b){a.Attribute(1,2);a.Put(0x400,0x87654321);a.Put(0x404,0x12345600u|b);Monstey_Check(Monstey_FearDbBoolByte(a.Read(),a.At(0x100),1,0xaa)==b,"bool must use DWORD stride");++Monstey_Cases;}++Monstey_Groups;}
void Monstey_VectorMatrix(){for(unsigned f=0;f<3;++f)for(unsigned type=0;type<256;++type)for(unsigned index=0;index<3;++index){Monstey_Arena a;a.Attribute(type,1);a.Put(0x400,a.At(0x600));for(unsigned i=0;i<4;++i){a.Put(0x600+i*4,0x80000001u+i*0x11111111u);a.Put(0x700+i*4,0xdead0000+i);}const auto result=Monstey_Vectors[f](a.Write(),a.At(0x100),index,a.At(0x700),a.At(0x800));Monstey_Check(result==a.At(0x800),"vector hidden result identity");for(unsigned i=0;i<f+2;++i)Monstey_Check(a.Get(0x800+i*4)==a.Get((type==f+6&&index==0?0x600:0x700)+i*4),"vector type and fallback");Monstey_Check(a.Get(0x800+(f+2)*4)==0,"vector wrote beyond width");++Monstey_Cases;}++Monstey_Groups;}
void Monstey_VectorAliases(){for(unsigned f=0;f<3;++f)for(int delta=-17;delta<=17;++delta)for(bool fallback:std::array{false,true}){Monstey_Arena a;a.Attribute(f+6,fallback?0:1);a.Put(0x400,a.At(0x600));for(unsigned i=0;i<80;++i)a.bytes[0x5d0+i]=static_cast<std::uint8_t>(i*37+11);const auto before=a.bytes;auto expected=before;const unsigned output=static_cast<unsigned>(0x600+delta);for(unsigned word=0;word<f+2;++word){std::array<std::uint8_t,4> loaded{};for(unsigned byte=0;byte<4;++byte)loaded[byte]=expected[0x600+word*4+byte];for(unsigned byte=0;byte<4;++byte)expected[output+word*4+byte]=loaded[byte];}Monstey_Vectors[f](a.Write(),a.At(0x100),0,a.At(0x600),a.At(output));Monstey_Check(a.bytes==expected,"vector alias copy order");++Monstey_Cases;}++Monstey_Groups;}
template<class Monstey_Call>void Monstey_ExpectFault(Monstey_Call&&call,Monstey_U32 at,bool writing){bool caught=false;try{call();}catch(const Monstey_FearDbFault&e){caught=e.address==at&&e.writing==writing;}Monstey_Check(caught,"consumed fault address/order");++Monstey_Cases;}
void Monstey_FaultOrder(){for(unsigned f=0;f<Monstey_Scalars.size();++f){Monstey_Arena a;a.Attribute(Monstey_Types[f],0);a.bytes.resize(0x10b);Monstey_Check(Monstey_Scalars[f](a.Read(),a.At(0x100),0,0xabcd)==0xabcd,"zero count must skip values pointer");++Monstey_Cases;a.bytes[0x10a]=static_cast<std::uint8_t>(Monstey_Types[f]);const Monstey_FearDbMemory suffix{a.At(0x10a),std::span<const std::uint8_t>(a.bytes).subspan(0x10a)};Monstey_ExpectFault([&]{(void)Monstey_Scalars[f](suffix,a.At(0x100),0,7);},a.At(0x108),false);a.bytes[0x10a]=0;Monstey_Check(Monstey_Scalars[f](suffix,a.At(0x100),0,7)==7,"type mismatch must skip count");++Monstey_Cases;}
 for(unsigned f=0;f<3;++f){Monstey_Arena a;a.Attribute(f+6);a.Put(0x400,a.At(0x1ffc));a.Put(0x1ffc,0x12345678);Monstey_ExpectFault([&]{Monstey_Vectors[f](a.Write(),a.At(0x100),0,a.At(0x700),a.At(0x800));},a.At(0x2000),false);Monstey_Check(a.Get(0x800)==0x12345678&&a.Get(0x804)==0,"source fault must retain earlier vector write");a.Put(0x400,a.At(0x600));a.Put(0x600,0x76543210);Monstey_ExpectFault([&]{Monstey_Vectors[f](a.Write(),a.At(0x100),0,a.At(0x700),a.At(0x1ffc));},a.At(0x2000),true);Monstey_Check(a.Get(0x1ffc)==0x76543210,"output fault must retain prior write");}
 {Monstey_Arena a;a.Put(0x108,0);a.bytes.resize(0x10c);Monstey_Check(Monstey_FearDbChildByIndex(a.Read(),a.At(0x100),0)==0,"bounded child reads pointer when empty");++Monstey_Cases;Monstey_ExpectFault([&]{(void)Monstey_FearDbAttributeByIndex(a.Read(),a.At(0x100),0);},a.At(0x10c),false);}++Monstey_Groups;}
}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("NEW report required");Monstey_Null();Monstey_Metadata();Monstey_Indices();Monstey_ScalarMatrix();Monstey_StoredZero();Monstey_Bools();Monstey_VectorMatrix();Monstey_VectorAliases();Monstey_FaultOrder();std::ofstream(argv[1],std::ios::binary)<<Monstey_Json::object({{"schema","Monstey.FearDbPrimitiveTests/1"},{"passed",true},{"groups",Monstey_Groups},{"cases",Monstey_Cases},{"checks",Monstey_Checks},{"synthetic_only",true},{"original_program_executed",false},{"original_x87_or_vtable_ABI_promoted",false}}).dump(2)<<'\n';std::cout<<"PASS "<<Monstey_Groups<<" groups "<<Monstey_Cases<<" cases "<<Monstey_Checks<<" checks\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
